Let us introduce the Christoffel--Darboux (CD) kernel  $p\times q$ matrix polynomial, $K^{[n]}(x,y)$:
	\begin{align} \label{CDkernel}
		K^{[n]}(x,y) & \coloneq A^{[n]}(x)B^{[n]}(y) = \begin{bNiceMatrix}
			A_0^{(1)}(x) & \Cdots & A_{n}^{(1)}(x) \\
			\Vdots & & \Vdots \\
			A_0^{(p)}(x) & \Cdots & A_{n}^{(p)}(x)
		\end{bNiceMatrix} \begin{bNiceMatrix}
			B_0^{(1)}(y) & \Cdots & B_0^{(q)}(y) \\
			\Vdots & & \Vdots \\
			B_{n}^{(1)}(y) & \Cdots & B_{n}^{(q)}(y) 
		\end{bNiceMatrix},\\
		K^{[n]}_{a,b}(x,y) & = \sum_{i=0}^{n}A^{(a)}_i(x)B_i^{(b)}(y).
	\end{align}

\label{ProyectorK}
	For any given matrix polynomial of degree $N$, i.e., 
	\[P(x) = \sum_{i=0}^N P_i x^i, \quad P_i \in \mathbb{C}^{p\times p},\]
	the following projection property holds: 
	\begin{equation} \label{Eq ProyectorK}
		\begin{aligned}
			\int_{\Delta}K^{[n]}(x,t)\operatorname{d} \mu(t) P(t) &= P(x), &  n &\geq Np + p -1.
		\end{aligned}
	\end{equation}

Using the orthogonality relations, for $n \geq Np + p-1$, it is straightforward to verify that: 
	\begin{equation*}
		\int_\Delta \begin{bNiceMatrix}
			B_n^{(1)}(t) & \Cdots & B_n^{(q)}(t)
		\end{bNiceMatrix} \operatorname{d} \mu(t) P(t) = 0.
	\end{equation*}
	Consequently, the result is independent of $n$: 
	\begin{equation*}
		A^{[n]}(x)\int_{\Delta}B^{[n]}(t) \operatorname{d} \mu(t) P(t) = A^{[Np+p]}(x)\int_{\Delta}B^{[Np+p]}(t) \operatorname{d} \mu(t) P(t) = A(x)\int_{\Delta}B(t) \operatorname{d} \mu(t) P(t).
	\end{equation*}
	Now, we prove the projection property for $n \rightarrow \infty$, 
	\begin{align*}
		A(x)\int_{\Delta}B(t) \operatorname{d} \mu(t) P(t) = X_{[p]}^\top(x) \Bar{S}^\top H^{-1}S \int_\Delta X_{[q]}(t) \operatorname{d} \mu(t) X_{[p]}^\top(t) \begin{bNiceMatrix}
			P_0 \\ \Vdots \\ P_N \\ 0_p \\ \Vdots
		\end{bNiceMatrix}= X_{[p]}^\top(x)\begin{bNiceMatrix}
			P_0 \\ \Vdots \\ P_N \\ 0_p \\ \Vdots
		\end{bNiceMatrix} = P(x).
	\end{align*}
	To achieve the stated result, we have used the definition of the moment matrix and its Gauss--Borel factorization.

We have
	\begin{align*}
		C(z) & = \int_\Delta \frac{\operatorname{d} \mu(x)}{z-x}A(x) = \frac{1}{z} \int_\Delta \frac{\operatorname{d} \mu(x)}{1-\frac{x}{z}}A(x) = \frac{1}{z}\int_\Delta \sum_{i=0}^\infty \left( \frac{x}{z} \right)^i \operatorname{d} \mu(x) A(x) \\[3pt]
		& = \frac{1}{z} X_{[q]}^\top(z^{-1})\int_\Delta X_{[q]}(x) \operatorname{d} \mu(x) X^\top_{[p]}(x) \Bar{S}^\top H^{-1} = \frac{1}{z} X_{[q]}(z^{-1}) S^{-1}.
	\end{align*}
	The expansion of $(1-\frac{x}{z})^{-1}$ in a power series is valid since $\lvertz\rvert > \mathrm{sup}\{ \lvertx\rvert: x \in \Delta \}$. A similar proof can be given for $D(z)$.

The mixed Christoffel--Darboux kernels are defined as follows:
	\begin{align*}
		K^{[n]}_{C}(x,y) & \coloneq C^{[n]}(x)B^{[n]}(y) = \int_\Delta \frac{\operatorname{d} \mu(t)}{x-t}K^{[n]}(t,y), \\
		K^{[n]}_{D}(x,y) & \coloneq A^{[n]}(x)D^{[n]}(y) = \int_\Delta K^{[n]}(x,t)\frac{\operatorname{d} \mu(t)}{y-t}.
	\end{align*}

Expanding the determinant we get
	\begin{align*}
		\det  R(x) & =  \begin{vmatrix}
			\left[ R^1_{N-1} \right]x^{N-1}+O(x^{N-2}) & x^{N}I_{(p-r)} + O(x^{N-1}) \\
			\\
			x^{N-1}I_{r} + O(x^{N-2}) & \left[ R^3_{N-1} \right]x^{N-1}+O(x^{N-2})
		\end{vmatrix} \\
		& = \sum_{\sigma \in \mathcal{S}_p} \text{sgn}(\sigma) R_{1\sigma(1)}R_{2\sigma(2)} \cdots R_{p\sigma(p)} \\&

			= \text{sgn}(\Tilde{\sigma}) R_{1\Tilde{\sigma}(1)}R_{2\Tilde{\sigma}(2)} \cdots R_{(p-r)\Tilde{\sigma}(p-r)} \cdots R_{p\Tilde{\sigma}(p)}      
			+ \sum_{\sigma \neq \Tilde{\sigma}} \text{sgn}(\sigma) R_{1\sigma(1)}R_{2\sigma(2)} \cdots R_{p\sigma(p)},

	\end{align*}
	where the permutation $\Tilde{\sigma}(i)$ is such that $i \rightarrow r+i$ for $i \leq (p-r)$ and $i \rightarrow i-(p-r)$ for $i \geq (p-r)+1$. This term in the determinant expansion leads to a contribution of the form:
	\begin{multline*}
		\operatorname{sgn}(\Tilde{\sigma}) R_{1\Tilde{\sigma}(1)}R_{2\Tilde{\sigma}(2)} \cdots R_{(p-r)\Tilde{\sigma}(p-r)} \cdots R_{p\Tilde{\sigma}(p)} \\\begin{aligned}
			&= \operatorname{sgn}(\Tilde{\sigma}) R_{1,(r+1)}R_{2,(r+2)} \cdots R_{(p-r),p} R_{(p-r+1),1} \cdots R_{pr} =     
			\operatorname{sgn}(\Tilde{\sigma}) (x^N)^{(p-r)}(x^{N-1})^{r} = x^{Np-r}.
		\end{aligned}
	\end{multline*} 	
	Any other permutation either results in zero or produces terms of lower degree.

We have
\begin{equation*}
	R\left( \Lambda_{[p]}^\top \right) = \left[\begin{NiceMatrix}
		R_0 & 0_p & 0_p & \Cdots \\
		R_1 & R_0 & 0_p & \Cdots \\
		\Vdots & & \Ddots & \\
		R_N & R_{N-1} & \Cdots & R_0 & \Cdots \\
		0_p & R_N & R_{N-1} & \Cdots & R_0 & \Cdots\\
		\Vdots & \Ddots[shorten-end=-10pt] &  \Ddots[shorten-end=-10pt] &  \Ddots[shorten-end=-25pt] &  & \Ddots
	\end{NiceMatrix} \right].
\end{equation*}
The block 
\begin{equation*}
	\begin{bmatrix}
		R_{N-1} & R_{N-2} \\
		R_N & R_{N-1}  
	\end{bmatrix} =\begin{bmatrix}
		\left[ R^1_{N-1} \right]_{(p-r)\times r} & & \left[ R^2_{N-1} \right]_{(p-r)\times (p-r)} & & &  \\ 
		& & & & R_{N-2} & \\
		I_{r\times r} & & \left[ R^4_{N-1} \right]_{r \times (p-r)} &  &  & \\ \\
		0_{(p-r)\times r} & & I_{(p-r)} & \left[ R^1_{N-1} \right]_{(p-r)\times r} & & \left[ R^2_{N-1} \right]_{(p-r)\times (p-r)} \\ \\
		0_{r\times r} & & 0_{r \times (p-r)} & I_{r\times r} & & \left[ R^4_{N-1} \right]_{r \times (p-r)}
	\end{bmatrix}
\end{equation*} has $p-r$ subdiagonals. Up to the matrix $R_{N-1}$, there will be $M-1$ matrices, which sum up to a total of $Np-r$ subdiagonals.

\label{ProyectorK-2}
    If the leading matrix of a given polynomial of degree $N$ is of the form: 
    \begin{equation*}
        P_N = \begin{bNiceMatrix}
            0_{(p-r) \times r} & I_{(p-r)} \\[2pt]
            0_r & 0_{r \times (p-r)}
        \end{bNiceMatrix},
    \end{equation*}
    then the projection property shown in Proposition \ref{ProyectorK}  holds for $n \geq Np + p -1 - r$.
\begin{proof}
    For $0 \leq i \leq p-1$, we have: 
    \begin{align*}
        \sum_{a=1}^p \sum_{b=1}^q \int_\Delta B_{Np+p-1-i}^{(b)}(t) \operatorname{d} \mu_{b,a}(t) \left( P(t) \right)_{a,\Tilde{a}} = \sum_{a=1}^p \left[ \sum_{b=1}^q \int_\Delta B_{Np+p-1-i}^{(b)}(t) \operatorname{d} \mu_{b,a}(t) t^N \right] \left( P_N \right)_{a,\Tilde{a}}.
    \end{align*}
    It is known that $\left( P_N \right)_{a,\Tilde{a}} = 0$ for $\Tilde{a}, a = \{ p-r+1, \dots, p \}$, 
    \begin{align*}
        \sum_{a=1}^p \left[ \sum_{b=1}^q \int_\Delta B_{Np+p-1-i}^{(b)}(t) \operatorname{d} \mu_{b,a}(t) t^N \right] \left( P_N \right)_{a,\Tilde{a}} = \sum_{a=1}^{p-r} \left[ \sum_{b=1}^q \int_\Delta B_{Np+p-1-i}^{(b)}(t) \operatorname{d} \mu_{b,a}(t) t^N \right] \left( P_N \right)_{a,\Tilde{a}},
    \end{align*}
    To eliminate the last term by using the orthogonality relations, we have to choose $i$ such that: 
    \begin{equation*}
        \ceil[\Big]{\frac{Np-1+i-a+2}{p}} - 1 \geq \ceil[\Big]{\frac{Np-1+i-p+r+2}{p}} - 1 \geq N. 
    \end{equation*}
    Therefore, $i \leq r$, and the result is independent of $n$ for $n \geq Np + p - 1 - r$.
\end{proof}

For $0 \leq i \leq p-1$, we have: 
    \begin{align*}
        \sum_{a=1}^p \sum_{b=1}^q \int_\Delta B_{Np+p-1-i}^{(b)}(t) \operatorname{d} \mu_{b,a}(t) \left( P(t) \right)_{a,\Tilde{a}} = \sum_{a=1}^p \left[ \sum_{b=1}^q \int_\Delta B_{Np+p-1-i}^{(b)}(t) \operatorname{d} \mu_{b,a}(t) t^N \right] \left( P_N \right)_{a,\Tilde{a}}.
    \end{align*}
    It is known that $\left( P_N \right)_{a,\Tilde{a}} = 0$ for $\Tilde{a}, a = \{ p-r+1, \dots, p \}$, 
    \begin{align*}
        \sum_{a=1}^p \left[ \sum_{b=1}^q \int_\Delta B_{Np+p-1-i}^{(b)}(t) \operatorname{d} \mu_{b,a}(t) t^N \right] \left( P_N \right)_{a,\Tilde{a}} = \sum_{a=1}^{p-r} \left[ \sum_{b=1}^q \int_\Delta B_{Np+p-1-i}^{(b)}(t) \operatorname{d} \mu_{b,a}(t) t^N \right] \left( P_N \right)_{a,\Tilde{a}},
    \end{align*}
    To eliminate the last term by using the orthogonality relations, we have to choose $i$ such that: 
    \begin{equation*}
        \ceil[\Big]{\frac{Np-1+i-a+2}{p}} - 1 \geq \ceil[\Big]{\frac{Np-1+i-p+r+2}{p}} - 1 \geq N. 
    \end{equation*}
    Therefore, $i \leq r$, and the result is independent of $n$ for $n \geq Np + p - 1 - r$.

\label{ConnectM}
    The moment matrices satisfy the following relation:
    \begin{equation*}
        \check{\mathscr{M}}R(\Lambda_{[p]}^\top) = \mathscr{M}.
    \end{equation*}

\label{ConnectAB}
    The following relations hold:
\[    \begin{aligned}
        \check{A}(x) \Omega &= R(x) A(x), & \Omega B(x) &= \check{B}(x).
    \end{aligned}\]

These follow from the definitions of $\check{A}(x), \: A(x), \: \check{B}(x), \: B(x)$, and Proposition \ref{MatrixConnect}. For instance,
    \begin{equation*}
        \check{B}(x) = \check{S}X_{[q]}(x) = \check{S}S^{-1}SX_{[q]}(x) = \Omega B(x).
    \end{equation*}

\label{ConnectCD}
    In terms of the Cauchy transforms of the original and perturbed orthogonal polynomials, the connection formulas are given by:
    \begin{align}
        \label{EqConnectC} \check{C}(x) \Omega &= C(x), \\
        \label{EqConnectD} \check{D}(x) R(x) &= \Omega D(x) + \int_\Delta \check{B}(y) \operatorname{d} \check{\mu}(y) \frac{R(x) - R(y)}{x-y}.
    \end{align}

We will prove the second relation, as the first can be shown similarly. We have:
    \begin{align*}
        \Omega D(x) &= \int_\Delta \Omega B(y) \frac{\operatorname{d} \mu(y)}{x-y} = \int_\Delta \check{B}(y) \frac{\operatorname{d} \mu(y)}{x-y} \\
        &=  \int_\Delta \check{B}(y) \frac{\operatorname{d} \check{\mu}(y)R(y)}{x-y} \\
        &= \check{D}(x)R(x) - \int_\Delta \check{B}(y) \frac{\operatorname{d} \check{\mu}(y)R(x)}{x-y} + \int_\Delta \check{B}(y) \frac{\operatorname{d} \check{\mu}(y)R(y)}{x-y}.
    \end{align*}

Using the identity:
    \begin{equation*}
        x^n - y^n = (x-y)\left( \sum_{i=1}^n x^{n-i}y^{i-1} \right),
    \end{equation*}
   it is straightforward to verify that:
   \begin{equation}\label{eq:Rxy}
       \frac{R(x) - R(y)}{x-y} = \sum_{i=1}^N R_i \sum_{j=1}^i \left( x^{i-j}y^{j-1} \right).
   \end{equation}
   Hence, it is a polynomial in both $x$ and $y$.

\label{D and W bb}
  For $i\in\{1,\dots,M\}$ and $n\in\mathbb{N}_0$  we introduce the following notation
\[    \begin{aligned}
        \mathbb{D}_n^{(i)} & \coloneq \sum_{a=1}^p D_n^{(a)}(x_i)v_{i;a}^R, & \mathbb{W}_n^{(i)} & \coloneq \sum_{b=1}^q B_n^{(b)}(x_i)\xi_{i;b}(x_i)\boldsymbol{v}_{i}^L R'(x_i) \boldsymbol{v}_{i}^R. 
    \end{aligned}  \]

\label{OmegaComponents}
    For $n \geq M$, the entries of $\Omega$ are subject to the inhomogeneous linear system
    \begin{equation} \label{EqOmegaComponents-n>M}
        \begin{bNiceMatrix}
            \Omega_{n,n-M} & \Cdots & \Omega_{n,n-1} 
        \end{bNiceMatrix}  \begin{bNiceMatrix}
        \mathbb{D}_{n-M}^{(1)}- \mathbb{W}_{n-M}^{(1)} & \Cdots & \mathbb{D}_{n-M}^{(M)} - \mathbb{W}_{n-M}^{(M)}\\
        \Vdots & & \Vdots\\
        \mathbb{D}_{n-1}^{(1)} - \mathbb{W}_{n-1}^{(1)}& \Cdots & \mathbb{D}_{n-1}^{(M)} - \mathbb{W}_{n-1}^{(M)}
        \end{bNiceMatrix}= - \begin{bNiceMatrix}
            \mathbb{D}_n^{(1)}- \mathbb{W}_n^{(1)}& \Cdots & \mathbb{D}_n^{(M)} - \mathbb{W}_n^{(M)}
        \end{bNiceMatrix}. 
    \end{equation}

We cannot directly evaluate Equation \eqref{EqConnectD} at $x_i$, so we examine the following limit:
    \begin{align*}
        \lim_{x \rightarrow x_i} \check{D}(x) R(x) \boldsymbol{v}_{i}^R &= \lim_{x \rightarrow x_i} \left( \int_\Delta \check{B}(y) \frac{\operatorname{d} \mu(y)}{x-y}R^{-1}(y)R(x) + \sum_{j=1}^M \check{B}(x_j) \boldsymbol{\xi}(x_j)_j\boldsymbol{v}_{j}^L\frac{R(x)}{x-x_j}  \right) \boldsymbol{v}_{i}^R \\
        &= \check{B}(x_i) \boldsymbol{\xi}(x_i)_i\boldsymbol{v}_{i}^L \lim_{x \rightarrow x_i} \frac{R(x)-R(x_i)}{x-x_i} \boldsymbol{v}_{i}^R,
    \end{align*}
    where we have used the fact that $R(x_i)\boldsymbol{v}_{i}^R = 0$. The term that remains non-zero can be rewritten as
    \begin{equation*}
        \lim_{x \rightarrow x_i} \check{D}(x) R(x) \boldsymbol{v}_{i}^R = \check{B}(x_i) \boldsymbol{\xi}(x_i)_i\boldsymbol{v}_{i}^L R'(x_i) \boldsymbol{v}_{i}^R. 
    \end{equation*} 

    Let us now focus on the case $n \geq M$. By using the orthogonality relations for $B(x)$ and taking into account Proposition \ref{R-BivaMP} (see proof of Corollary \ref{ProyectorK-2}),
    \begin{equation*}
\begin{aligned}
	        \sum_{a=1}^p\sum_{b=1}^q \int_\Delta \check{B}_n^{(b)}(y) \operatorname{d} \check{\mu}_{b,a}(y) \frac{\left( R(x)-R(y) \right)_{a,\Tilde{a}}}{x-y} &= 0, & \Tilde{a}&\in \{1,\dots, p\}.
\end{aligned}
    \end{equation*}
    Taking the limit in Equation \eqref{EqConnectD} when $x \rightarrow x_i$, then multiplying by the corresponding right eigenvector, and finally considering the $n$-th component, we find
    \begin{equation*}
        \sum_{b=1}^q\check{B}_n^{(b)}(x_i) \xi_{i;b}(x_i)\boldsymbol{v}_{i}^L R'(x_i) \boldsymbol{v}_{i}^R = \left( \Omega D(x_i) \boldsymbol{v}_{i}^R \right)^{[n]}.  
    \end{equation*}
    Recalling Proposition \ref{ConnectAB}, we obtain
    \begin{multline*}
         \sum_{b=1}^q\left( B_n^{(b)}(x_i) + \Omega_{n,n-1}B_{n-1}^{(b)}(x_i) + \cdots + \Omega_{n,n-M}B_{n-M}^{(b)}(x_i) \right)\xi_{i;b}\boldsymbol{v}_{i}^L R'(x_i) \boldsymbol{v}_{i}^R   \\
         = \left( D_n^{(a)}(x_i) + \Omega_{n,n-1}D_{n-1}^{(a)}(x_i) + \cdots + \Omega_{n,n-M}D_{n-M}^{(a)}(x_i) \right) v_{i;a}^R,
    \end{multline*}
    and using the notation introduced, we can write
    \begin{equation*}
        \mathbb{W}_n^{(i)}+ \Omega_{n,n-1}\mathbb{W}_{n-1}^{(i)}+ \cdots + \Omega_{n,n-M}\mathbb{W}_{n-M}^{(i)}= \mathbb{D}_n^{(i)}+ \Omega_{n,n-1}\mathbb{D}_{n-1}^{(i)}+ \cdots + \Omega_{n,n-M}\mathbb{D}_{n-M}^{(i)}.
    \end{equation*}
    Rearranging the equation yields
    \begin{equation*}
        - \left( \mathbb{D}_n^{(i)}- \mathbb{W}_n^{(i)}\right) = \begin{bNiceMatrix}
            \Omega_{n,n-M} & \Cdots & \Omega_{n,n-1} 
        \end{bNiceMatrix}\begin{bNiceMatrix}
            \mathbb{D}_{n-M}^{(i)}- \mathbb{W}_{n-M}^{(i)}\\
            \Vdots \\
            \mathbb{D}_{n-1}^{(i)}- \mathbb{W}_{n-1}^{(i)}
        \end{bNiceMatrix}. 
    \end{equation*}
    Considering the $M$ distinct roots, it is straightforward to arrive at the stated equation.

Let us introduce the following determinantal expressions:
    \begin{equation*}
\begin{aligned}
	        \tau_n^{(i)} &\coloneq \begin{vNiceMatrix}
            \mathbb{D}_{n-M}^{(1)} - \mathbb{W}_{n-M}^{(1)}& \Cdots & \mathbb{D}_{n-M}^{(M)}- \mathbb{W}_{n-M}^{(M)} \\
            \Vdots & & \Vdots \\
            \mathbb{D}_{n-i-1}^{(1)}- \mathbb{W}_{n-i-1}^{(1)}& \Cdots & \mathbb{D}_{n-i-1}^{(M)}- \mathbb{W}_{n-i-1}^{(M)}\\[5pt]
            \mathbb{D}_{n-i+1}^{(1)}- \mathbb{W}_{n-i+1}^{(1)}& \Cdots & \mathbb{D}_{n-i+1}^{(M)}- \mathbb{W}_{n-i+1}^{(M)}\\
            \Vdots & & \Vdots \\
            \mathbb{D}_{n}^{(1)}- \mathbb{W}_{n}^{(1)}& \Cdots & \mathbb{D}_{n}^{(M)}- \mathbb{W}_{n}^{(M)}
        \end{vNiceMatrix}, & i& \in \{0, \cdots, M \}, & n & \in \{M,M+1,M+2,\dots\}.
\end{aligned}
    \end{equation*}
    For \( i = M \), we will also use the notation $\tau_{n} \coloneq \tau_{n+1}^{(M)}$, $ n  \in\{M-1,M,M+1,\dots\}$.

\label{ConnectKernelmix}
    The connection formulas for the mixed \( CD \) kernels, for \( n \geq M \), are given by:
    \begin{multline} \label{EqConnectKernelmix-n>M}
        \check{K}^{[n-1]}_{D}(x,y)R(y) = \frac{R(x) - R(y)}{x - y} + R(x)K^{[n-1]}_D (x,y) \\[3pt]
        - \begin{bNiceMatrix}
            \check{A}_n^{(1)}(x)  & \Cdots & \check{A}_{n+M-1}^{(1)}(x) \\
            \Vdots & & \Vdots \\
            \check{A}_n^{(p)}(x) & \Cdots & \check{A}_{n+M-1}^{(p)}(x)
        \end{bNiceMatrix}
        \begin{bNiceMatrix}                     
            \Omega_{n,n-M} & \Cdots & & \Omega_{n,n-1} \\
            0 & & & \\
            \Vdots & \Ddots & \Ddots[shorten-end=-8pt] & \Vdots \\
            0 & \Cdots & 0 & \Omega_{n+M-1,n-1}
        \end{bNiceMatrix}
        \begin{bNiceMatrix}
            D^{(1)}_{n-M}(y) & \Cdots & D^{(q)}_{n-M}(y) \\
            \Vdots & & \Vdots \\
            D^{(1)}_{n-1}(y) & \Cdots & D^{(q)}_{n-1}(y)
        \end{bNiceMatrix}. 
    \end{multline}

For \( n \geq M \), using Equation \eqref{EqConnectD}, we find:
    \begin{equation*}
        \check{K}^{[n-1]}_{D}(x,y)R(y) = \check{A}(x) \Pi_{n-1} \check{D}(y)R(y) = \check{A}(x) \Pi_{n-1}  \Omega D(y) + \check{A}(x)\Pi_{n-1}  \int_{\Delta} \check{B}(t) \, \operatorname{d} \mu(t) \frac{R(t) - R(y)}{t - y}.
    \end{equation*}
    Using Proposition \ref{ProyectorK} and \ref{R-BivaMP} , the last term equals \( \frac{R(x) - R(y)}{x - y} \). On the other hand,
    \begin{equation*}
        \check{A}(x) \Pi_{n-1}  \Omega D(y) = \check{A}(x) \Omega \Pi_{n-1}  D(y) - \check{A}(x) [\Omega, \Pi_{n-1} ] D(y).
    \end{equation*}
    From Proposition \ref{ConnectAB} and Equation \eqref{Commutator}, we obtain
    \begin{multline*}
        \check{A}(x) \Pi_{n-1}  \Omega D(y) = R(x)K^{[n-1]}_D (x,y) 
  - \begin{bNiceMatrix}
            \check{A}_n^{(1)}(x)  & \Cdots & \check{A}_{n+M-1}^{(1)}(x) \\
            \Vdots & & \Vdots \\
            \check{A}_n^{(p)}(x) & \Cdots & \check{A}_{n+M-1}^{(p)}(x)
        \end{bNiceMatrix}
        \begin{bNiceMatrix}                     
            \Omega_{n,n-M} & \Cdots & & \Omega_{n,n-1} \\
            0 & & & \\
            \Vdots & \Ddots & \Ddots[shorten-end=-8pt] & \Vdots \\
            0 & \Cdots & 0 & \Omega_{n+M-1,n-1}
        \end{bNiceMatrix} \\
 \times \begin{bNiceMatrix}
            D^{(1)}_{n-M}(y) & \Cdots & D^{(q)}_{n-M}(y) \\
            \Vdots & & \Vdots \\
            D^{(1)}_{n-1}(y) & \Cdots & D^{(q)}_{n-1}(y)
        \end{bNiceMatrix}.
    \end{multline*}
    Thus, the desired relation follows immediately.

\label{K bb}
   Let us introduce the following vector polynomials: 
    \begin{equation*}
        \mathbb{K}^{[n-1],(i)}(x) \coloneq K^{[n-1]}_D (x,x_i)\boldsymbol{v}_{i}^R - K^{[n-1]}(x,x_i)\boldsymbol{\xi}_i \boldsymbol{v}_{i}^L R'(x_i) \boldsymbol{v}_{i}^R.
    \end{equation*}
    \begin{Proposition} \label{Futuro Tau}
    	    The following holds
    	    	\begin{multline} \label{EqSistLinealTau0}  
    	    		R(x)  \begin{bNiceMatrix}
    	    			\mathbb{K}^{[n-1],(1)}(x) + \frac{\boldsymbol{v}_{1}^R}{x-x_1} & \Cdots & \mathbb{K}^{[n-1],(M)}(x) + \frac{\boldsymbol{v}_{M}^R}{x-x_M}
    	    		\end{bNiceMatrix} \\ = \begin{bNiceMatrix}
