            B_{n-1}^{(b)}(x)
        \end{bNiceMatrix}.
    \end{align*}
    Using now Proposition \ref{OmegaComponents}, this can be rewritten as: 
    \begin{align*}
        \check{B}_n^{(b)}(x) =  B_n^{(b)}(x) - & \begin{bNiceMatrix}
            \mathbb{D}_n^{(1)}- \mathbb{W}_n^{(1)}& \Cdots & \mathbb{D}_n^{(M)}- \mathbb{W}_n^{(M)}
        \end{bNiceMatrix} & \begin{bNiceMatrix}
            \mathbb{D}_{n-M}^{(1)}- \mathbb{W}_{n-M}^{(1)}& \Cdots & \mathbb{D}_{n-M}^{(M)}- \mathbb{W}_{n-M}^{(M)}\\
            \Vdots & & \Vdots\\
            \mathbb{D}_{n-1}^{(1)}- \mathbb{W}_{n-1}^{(1)}& \Cdots & \mathbb{D}_{n-1}^{(M)}- \mathbb{W}_{n-1}^{(M)}
        \end{bNiceMatrix}^{-1}\begin{bNiceMatrix}
            B_{n-M}^{(b)}(x) \\
            \Vdots \\
            B_{n-1}^{(b)}(x)
        \end{bNiceMatrix}.
    \end{align*}
    And from this last relation it is straight forward to prove Equation \eqref{EqCheckB}.

\label{kbb reducido}
    The terms $\mathbb{K}_{a}^{[n],(i)}(x)$ can be re-expressed as follows:
    \begin{multline*}
        \mathbb{K}_{a}^{[n],(i)}(x) = \frac{1}{(x-x_i)} \left[ \sum_{j=1}^p \sum_{l=1}^j T_{n+l,n-p+j} A_{n+l}^{(a)}(x) \left( \mathbb{D}_{n+j-p}^{(i)} - \mathbb{W}_{n+j-p}^{(i)} - D_{n+j-p}(x)\boldsymbol{v}_i^R \right) \right. \\ - \left. \sum_{j=0}^{q-1} \sum_{l=0}^j T_{n-l,n+q-j} A_{n-l}^{(a)}(x) \left( \mathbb{D}_{n+q-j}^{(i)} - \mathbb{W}_{n+q-j}^{(i)} - D_{n+q-j}(x)\boldsymbol{v}_i^R \right)\right]. 
    \end{multline*}

\label{Remark1}
    From the second equation in Proposition \ref{ConnectAB}, one could also study the relation for $n < M$: 
    \begin{equation*}
        \check{B}_n^{(b)}(x) = \Omega_{n,0}B_{0}^{(b)}(x) + \dots + \Omega_{n,n-1}B_{n-1}^{(b)}(x) + B_n^{(b)}(x).
    \end{equation*}
    However, the explicit formulas for $\Omega_{i,j}$ when $i < M$ cannot be found. Studying the n-th component of Equation \eqref{EqConnectD}, taking the limit when $x \rightarrow x_i$ and acting on the right with $\boldsymbol{v}_i^R$ yields: 
    \begin{equation*}
        \left( \Omega B(x_i)\xi(x_i)\boldsymbol{v}_i^LR'(x_i)\boldsymbol{v}_i^R \right)^{[n]} = \left( \Omega D(x_i)\boldsymbol{v}_i^R - \lim_{x\rightarrow x_i}  \Omega\int_\Delta B(y) \operatorname{d} \check{\mu}(y) \frac{R(y)\boldsymbol{v}_i^R}{x-y} \right)^{[n]},
    \end{equation*}
    and explicitly decomposing the perturbed measure: 
    \begin{equation*}
        \Omega\int_\Delta B(y) \operatorname{d} \mu(y) \frac{\boldsymbol{v}_i^R}{x_i-y}-B(x_i)\xi(x_i)\lim_{x\rightarrow x_i}\frac{\boldsymbol{v}_i^LR(x_i)\boldsymbol{v}_i^R}{y-x_i} = \Omega D(x_i)\boldsymbol{v}_i^R - \Omega B(x_i)\xi(x_i)\boldsymbol{v}_i^LR'(x_i)\boldsymbol{v}_i^R . 
    \end{equation*}
    The relation is satisfied trivially and we cannot obtain any information on the $\Omega_{i,j}$.

   Nevertheless, we can assure that the maximum degrees for the $\check{B}_n^{(b)}(x)$ are reached for $n<M$. Since the maximum degrees appear in terms of the form $\check{B}_{ip+j}^{(1+j)}(x)$, 
   \begin{equation*}
       \check{B}_{ip+j}^{(1+j)}(x) = \check{B}_{ip+j}^{(1+j)}(x) + \Omega_{ip+j,ip+j-1} \check{B}_{ip+j-1}^{(1+j)}(x) + \dots + \Omega_{ip+j,0}\check{B}_{0}^{(1+j)}(x).
   \end{equation*}
   All the terms multiplied by the $\Omega$ components are strictly of lower degree and $\check{B}_{ip+j}^{(1+j)}(x)$ reaches the desired degree.

\label{LemmaEigenvectors}
    For a holomorphic matrix function $f(x)$ (with holomorphic entries) and a matrix polynomial $R(x)$, both of order $p$, the following holds:
    \begin{equation*}
        \sum_{l=0}^k \frac{1}{l!} \boldsymbol{v}_{i,j;k-l}^L \frac{\operatorname{d}^l}{\operatorname{d} x^l} \left[ R(x) f(x) \right]_{x=x_i} = 0,
    \end{equation*}
    where $\boldsymbol{v}_{i,j;k-l}$ is a Jordan vector and $k \leq \kappa_{i,j}-1$. The same result holds if we apply this expression on the left to the combination $f(x)R(x)$.

Differentiating $l$ times gives:
    \begin{equation*}
        \sum_{l=0}^k \frac{1}{l!} \boldsymbol{v}_{i,j;k-l}^L \sum_{m=0}^l \binom{l}{m}  R^{(m)}(x_i)f^{(l-m)}(x_i).
    \end{equation*}
    By changing the summation index as $\lambda = l-m$ and $\mu = m$, the expression becomes:
    \begin{equation*}
        \sum_{\lambda=0}^k \frac{1}{\lambda!} \left( \sum_{\mu=0}^{k-\lambda} \frac{1}{\mu!} \boldsymbol{v}_{i,j;k-\lambda-\mu}^L R^{(\mu)}(x_i) \right) f^{(\lambda)}(x_i).
    \end{equation*}
    This results in zero, as the term in parentheses represents the action of an appropriate Jordan chain on $R(x)$ and its derivatives.

The following limits:
    \begin{equation*}
\begin{aligned}
	        &\lim_{x \rightarrow x_i} \check{D}(x) R(x) \left( \sum_{l=0}^k \frac{1}{l!}\overleftarrow{\frac{\operatorname{d}^l}{\operatorname{d} x^l}} \boldsymbol{v}_{i,j;k-l}^R \right), & k&\in  \{ 0, \dots, \kappa_{i,j}-1 \},
\end{aligned}
    \end{equation*}
    exists and depends only on $R(x)$ and its derivatives, the canonical set of Jordan chains associated with the eigenvalue $x_i$ (both left and right), the matrix polynomial $\check{B}(x)$, and the vector functions $\boldsymbol{\xi}_{i,j,k}(x)$.

Explicitly, the limit is:
    \begin{multline*}
        \lim_{x \rightarrow x_i} \left[  \int_\Delta \check{B}(t) \operatorname{d} \mu(t) \frac{R^{-1}(t)R(x)}{x-t} \right.\\+ \int_{-\infty}^\infty\operatorname{d} t\sum_{\tilde{\imath}=1;\tilde{\imath} \neq i}^M\sum_{\tilde{\jmath}=1}^{s_{\tilde{\imath}}}\sum_{\tilde{k}=0}^{\kappa_{\tilde{\imath},\tilde{\jmath}}-1} \check{B}(t)\boldsymbol{\xi}_{\tilde{\imath},\tilde{\jmath},\tilde{k}}(t) \left( \sum_{\tilde{l}=0}^{\tilde{k}}\frac{(-1)^{\tilde{l}}}{\tilde{l}!} \boldsymbol{v}_{\tilde{\imath},\tilde{\jmath};\tilde{k}-\tilde{l}}^L\frac{\delta^{(\tilde{l})}(t-x_{\tilde{\imath}})}{x-t} R(x)\right)  \\
        \left. + \int_{-\infty}^\infty\operatorname{d} t\sum_{\tilde{\jmath}=1}^{s_{i}}\sum_{\tilde{k}=0}^{\kappa_{i,\tilde{\jmath}}-1}\check{B}(t)\boldsymbol{\xi}_{i,\tilde{\jmath},\tilde{k}}(t) \left( \sum_{\tilde{l}=0}^{\tilde{k}}\frac{(-1)^{\tilde{l}}}{\tilde{l}!} \boldsymbol{v}_{i,\tilde{\jmath};\tilde{k}-\tilde{l}}^L\frac{\delta^{(\tilde{l})}(t-x_i)}{x-t}R(x)\right)\right] \left( \sum_{l=0}^k \frac{1}{l!}\overleftarrow{\frac{\operatorname{d}^l}{\operatorname{d} x^l}} \boldsymbol{v}_{i,j;k-l}^R \right).
    \end{multline*}
    The first  integral term, as well as the summation term for $i \neq \tilde{\imath}$, vanishes because we have a holomorphic function at $x=x_i$, and we can apply Lemma \ref{LemmaEigenvectors}. The non-zero term simplifies as:
    \begin{multline*}
        \lim_{x \rightarrow x_i} \left(\sum_{\tilde{\jmath}=1}^{s_{i}}\sum_{\tilde{k}=0}^{\kappa_{i,\tilde{\jmath}}-1} \sum_{\tilde{l}=0}^{\tilde{k}}\sum_{m=0}^{\tilde{l}} \frac{1}{(\tilde{l}-m)!}\left[\check{B}(t)\boldsymbol{\xi}_{i,\tilde{\jmath},\tilde{k}}(t)\right]^{(\tilde{l}-m)}_{t=x_i}  \boldsymbol{v}_{i,\tilde{\jmath};\tilde{k}-\tilde{l}}^L\frac{R(x)}{(x-x_i)^{m+1}}\right) \left( \sum_{l=0}^k \frac{1}{l!}\overleftarrow{\frac{\operatorname{d}^l}{\operatorname{d} x^l} }\boldsymbol{v}_{i,j;k-l}^R \right).
    \end{multline*}
    Using the derivative product formula, the limit becomes:
    \begin{multline*}
        \lim_{x \rightarrow x_i} \left(\sum_{\tilde{\jmath},\tilde{k},\tilde{l},m} \sum_{l=0}^k \sum_{\lambda=0}^l \frac{1}{\lambda!(l-\lambda)!}\frac{(-1)^{\lambda}(m+\lambda)!}{m!(\tilde{l}-m)!}\left[\check{B}(t)\boldsymbol{\xi}_{i,\tilde{\jmath},\tilde{k}}(t)\right]^{(\tilde{l}-m)}_{t=x_i}  \boldsymbol{v}_{i,\tilde{\jmath};\tilde{k}-\tilde{l}}^L\frac{R^{(l-\lambda)}(x)}{(x-x_i)^{m+\lambda+1}}\boldsymbol{v}_{i,j;k-l}^R \right). 
    \end{multline*}
    Adjusting the summations on $l$ and $\lambda$ yields:
    \begin{multline*}
        \lim_{x \rightarrow x_i} \left(\sum_{\tilde{\jmath},\tilde{k},\tilde{l},m}  \sum_{\lambda=0}^k \sum_{\mu=0}^{k-\lambda} \frac{(-1)^{\lambda}(m+\lambda)!}{\lambda!m!(\tilde{l}-m)!}\left[\check{B}(t)\boldsymbol{\xi}_{i,\tilde{\jmath},\tilde{k}}(t)\right]^{(\tilde{l}-m)}_{t=x_i}  \boldsymbol{v}_{i,\tilde{\jmath};\tilde{k}-\tilde{l}}^L\frac{R^{(\mu)}(x)}{(x-x_i)^{m+\lambda+1}} \frac{1}{\mu ! }\boldsymbol{v}_{i,j;k-\lambda+\mu}^R \right).
    \end{multline*}
    By subtracting the following combination:
    \begin{equation*}
        \sum_{\tilde{\jmath},\tilde{k},\tilde{l},m,\lambda,\mu} \frac{(-1)^{\lambda}(m+\lambda)!}{\lambda!m!(\tilde{l}-m)!}\left[\check{B}(t)\boldsymbol{\xi}_{i,\tilde{\jmath},\tilde{k}}(t)\right]^{(\tilde{l}-m)}_{t=x_i}  \boldsymbol{v}_{i,\tilde{\jmath};\tilde{k}-\tilde{l}}^L\frac{1}{(x-x_i)^{m+\lambda+1}} \frac{1}{\mu ! }R^{(\mu)}(x_i)\boldsymbol{v}_{i,j;k-\lambda+\mu}^R,
    \end{equation*}
    which is always zero, the limit simplifies to:
    \begin{multline*}
         \sum_{\tilde{\jmath},\tilde{k},\tilde{l},m,\lambda,\mu} \frac{(-1)^{\lambda}(m+\lambda)!}{\lambda!\mu!m!(\tilde{l}-m)!}\left[\check{B}(t)\boldsymbol{\xi}_{i,\tilde{\jmath},\tilde{k}}(t)\right]^{(\tilde{l}-m)}_{t=x_i}  \lim_{x \rightarrow x_i} \left( \boldsymbol{v}_{i,\tilde{\jmath};\tilde{k}-\tilde{l}}^L\frac{R^{(\mu)}(x)-R^{(\mu)}(x_i)}{(x-x_i)^{m+\lambda+1}} \boldsymbol{v}_{i,j;k-\lambda+\mu}^R \right),
    \end{multline*}
    which only depends on the derivatives of $R(x)$, and the limit exists.

We define the following expressions:
\begin{align*}
    \mathbb{D}_{n,j}^{(i)}& \coloneq \begin{bNiceMatrix}
        D_n(x_i)\boldsymbol{v}^R_{i,j;0} & \Cdots & \displaystyle\sum_{l=0}^{\kappa_{i,j}-1} \frac{1}{l!} D^{(l)}_n(x_i)\boldsymbol{v}^R_{i,j;\kappa_{i,j}-1-l}
    \end{bNiceMatrix}, \\
    \mathbb{W}_{n,j}^{(i)}& \coloneq \begin{multlined}[t][.75\textwidth]
    	\lim_{x \rightarrow x_i}        
    \int_{-\infty}^\infty\operatorname{d} t	 \sum_{\tilde{\jmath}=1}^{s_i}\sum_{\tilde{k}=0}^{\kappa_{i,\tilde{\jmath}}-1}\sum_{\tilde{l}=0}^{\tilde{k}} \frac{(-1)^{\tilde{l}}}{\tilde{l}!} B(t)\boldsymbol{\xi}_{i,\tilde{\jmath},\tilde{k}}(t)  \boldsymbol{v}_{i,\tilde{\jmath};\tilde{k}-\tilde{l}}^L \frac{\delta^{(\tilde{l})}(t-x_i)R(x)}{(x-t)}\\
    \times	\begin{bNiceMatrix}
        \boldsymbol{v}^R_{i,j,0} & \Cdots &\displaystyle \sum_{l=0}^{\kappa_{i,j}-1} \frac{1}{l!} \overleftarrow{\dfrac{\operatorname{d}^l}{\operatorname{d} x^l}} \boldsymbol{v}^R_{i,j,\kappa_{i,j}-1-l}
    \end{bNiceMatrix},          
    \end{multlined}
\end{align*}
both of which are row vectors of length $\kappa_{i,j}$. Additionally, we define the vector:
\begin{equation*}
    \mathbb{D}_n^{(i)}-\mathbb{W}_n^{(i)}\coloneq \begin{bNiceMatrix}
        \mathbb{D}_{n,1}^{(i)}-\mathbb{W}_{n,1}^{(i)}& \Cdots & \mathbb{D}_{n,s_i}^{(i)}-\mathbb{W}_{n,s_i}^{(i)}
    \end{bNiceMatrix},
\end{equation*}
which has length $K_i$ (where $K_i$ represents the multiplicity of $x=x_i$ as a zero of $\det R(x)$).

We also introduce the vector:
\begin{equation*}
    \mathbb{K}^{[n-1],(i)}(x) \coloneq \sum_{r=0}^{n-1}A_r(x) \left( \mathbb{D}_r^{(i)}- \mathbb{W}_r^{(i)} \right),
\end{equation*}
and the following notations:
\begin{align*}
    \mathbb{P}_j^{(i)}(x) & \coloneq \begin{bNiceMatrix}
        \dfrac{\boldsymbol{v}_{i,j;0}}{x-x_i} & \Cdots & \displaystyle\sum_{l=0}^{\kappa_{i,j}-1} \frac{1}{l!} \frac{\operatorname{d}^l}{\operatorname{d} x^l} \left( \frac{1}{x-x_i} \right) \boldsymbol{v}^R_{i,j;\kappa_{i,j}-1-l}
    \end{bNiceMatrix}, \\
    \mathbb{P}^{(i)}(x) & \coloneq \begin{bNiceMatrix}
        \mathbb{P}_1^{(1)}(x) & \Cdots & \mathbb{P}_{s_i}^{(i)}(x)
    \end{bNiceMatrix}.
\end{align*}
Here, $\mathbb{P}_j^{(i)}(x)$ is of length $\kappa_{i,j}$, whereas $\mathbb{K}^{[n-1],(i)}(x)$ and $\mathbb{P}(x,x_i)$ have length $K_i$.

Within this framework, the $\tau$-determinants are expressed as:
\begin{equation*}
    \tau_{n} \coloneq \begin{vNiceMatrix}
        \mathbb{D}_{n-Np+r+1}^{(1)}- \mathbb{W}_{n-Np+r+1}^{(1)}& \Cdots & \mathbb{D}_{n-Np+r+1}^{(M)}- \mathbb{W}_{n-Np+r+1}^{(M)}\\
        \Vdots & & \Vdots \\
        \mathbb{D}_{n}^{(1)}- \mathbb{W}_{n}^{(1)}& \Cdots & \mathbb{D}_{n}^{(M)}- \mathbb{W}_{n}^{(M)}
    \end{vNiceMatrix},
\end{equation*}
with $n \in \{ Np+r-1, Np+r, Np+r+1, \dots  \} $.

We will highlight the key distinction between these formulas and those previously established (Equation \eqref{EqCheckA} and \eqref{EqCheckB}), particularly focusing on Equation \eqref{EqCheckA-AM}. In the proof of Proposition \ref{Futuro Tau}, when dealing with different Jordan chains, it becomes necessary to consider the term
    \begin{equation*}
        \frac{R(x)-R(y)}{x-y}\left( \sum_{l=0}^k\frac{1}{l!} \overleftarrow{\frac{\operatorname{d}^l}{\operatorname{d} y^l}} \boldsymbol{v}^R_{i,j;k-1-l} \right)_{y=x_i},
    \end{equation*}
    which, by applying Lemma \ref{LemmaEigenvectors}, can be reformulated as:
    \begin{equation*}
        R(x)\left( \sum_{l=0}^k\frac{1}{l!} \frac{\operatorname{d}^l}{\operatorname{d} y^l}\left[ \frac{1}{x-y} \right]_{y=x_i} \boldsymbol{v}^R_{i,j;k-1-l} \right).
    \end{equation*}
    This expression is simply \( R(x) \) multiplied by the \( k \)-th component of the vector \( \mathbb{P}_j(x,x_i) \). Hence, the formulas generalize from 
    \begin{equation*}
        \mathbb{K}^{[n-1],(i)}(x) + \frac{\boldsymbol{v}_{i}}{x-x_i}, 
    \end{equation*}
    in the simple eigenvalue case, to 
    \begin{equation*}
        \mathbb{K}^{[n-1],(i)}(x) + \mathbb{P}^{(i)}(x),
    \end{equation*}
    in the more general case.

Let us now extend the proof of Theorem \ref{ExistsTheorem} to the present context. Proposition \ref{Futuro Tau} can be restated as follows:
    \begin{multline*}  
    	R(x)  \begin{bNiceMatrix}
    	\mathbb{K}^{[n-1],(1)}(x) + \mathbb{P}^{(1)}(x) & \Cdots & \mathbb{K}^{[n-1],(M)}(x) + \mathbb{P}^{(M)}(x)
    	\end{bNiceMatrix} \\ = \begin{bNiceMatrix}
    	    \check{A}_n^{(1)}(x)  & \Cdots & \check{A}_{n+Np-r-1}^{(1)}(x) \\
    	    \Vdots & & \Vdots \\
    	    \check{A}_n^{(p)}(x) & \Cdots & \check{A}_{n+Np-r-1}^{(p)}(x)
    	\end{bNiceMatrix} \begin{bNiceMatrix}
    	    \Omega_{n,n-Np+r} & \Cdots & & \Omega_{n,n-1} \\
    	    0 & & &   \\
    	    \Vdots & \Ddots & \Ddots[shorten-end=-8pt] & \Vdots \\
    	    0 & \Cdots & 0 & \Omega_{n+Np-r-1,n-1}
    	\end{bNiceMatrix} \\\times\begin{bNiceMatrix}
    	\mathbb{D}_{n-Np+r}^{(1)}- \mathbb{W}_{n-Np+r}^{(1)}& \Cdots & \mathbb{D}_{n-Np+r}^{(M)}- \mathbb{W}_{n-Np+r}^{(M)}\\
    	    \Vdots & & \Vdots \\
    	    \mathbb{D}_{n-1}^{(1)}- \mathbb{W}_{n-1}^{(1)}& \Cdots & \mathbb{D}_{n-1}^{(M)}- \mathbb{W}_{n-1}^{(M)}
    	\end{bNiceMatrix}.
    \end{multline*}
    Assuming that orthogonality holds even when \( \tau_{n-1} = 0 \), there exists a vector \( \boldsymbol{c} \) of size \( Np-r \), such that by studying points where \( \det R(x) \neq 0 \):
    \begin{equation*}
        \begin{bNiceMatrix}
    	\mathbb{K}^{[n-1],(1)}(x) + \mathbb{P}^{(1)}(x) & \Cdots & \mathbb{K}^{[n-1],(i)}(x) + \mathbb{P}^{(i)}(x) & \Cdots & \mathbb{K}^{[n-1],(M)}(x) + \mathbb{P}^{(M)}(x)
    	\end{bNiceMatrix} \boldsymbol{c} = 0.
    \end{equation*}
    Let us now examine \( \mathbb{P}^{(i)}(x) \) in closer detail. The vector contains derivatives of \( \frac{1}{x-y} \) evaluated at \( y = x_i \), which are poles whose multiplicity depends on the order of the derivative. Specifically, we have:
    \begin{equation*}
        \mathbb{P}^{(i)}(x) = \begin{bNiceMatrix}
            \frac{\boldsymbol{v}_{i,1;0}^R}{x-x_i} & \Cdots & \sum_{l=0}^{\kappa_{i,1}-2} \frac{\boldsymbol{v}_{i,1;\kappa_{i,1}-2-l}^R}{(x-x_i)^{l+1}} & \sum_{l=0}^{\kappa_{i,1}-1} \frac{\boldsymbol{v}_{i,1;\kappa_{i,1}-1-l}^R}{(x-x_i)^{l+1}} & \Cdots &\frac{\boldsymbol{v}_{i,s_i;0}^R}{x-x_i} & \Cdots & \sum_{l=0}^{\kappa_{i,s_i}-1} \frac{\boldsymbol{v}_{i,s_i;\kappa_{i,s_i}-1-l}^R}{(x-x_i)^{l+1}}
        \end{bNiceMatrix}.
    \end{equation*}
    Multiplying the expression by \( (x-x_i)^{\kappa_{i,j}-1} \), where \( \kappa_{i,j} \) is the largest partial multiplicity, we integrate the relation over the complex plane using a counterclockwise contour \( C_i \) around \( x_i \) (and not any other eigenvalue):
    \begin{equation*}
        \oint_{C_i} (z-x_i)^{\kappa_{i,j}-1} \begin{bNiceMatrix}
			\mathbb{K}^{[n-1],(1)}(z) + \mathbb{P}^{(1)}(z) & \Cdots & \mathbb{K}^{[n-1],(M)}(z) + \mathbb{P}^{(M)}(z)
		\end{bNiceMatrix} \boldsymbol{c} \: \operatorname{d} z.
    \end{equation*}
    The only nonzero terms will correspond to those involving poles of multiplicity \( \kappa_{i,j} \), which are associated with Jordan chains of length \( \kappa_{i,j} \). Without loss of generality, assume that the partial multiplicities for \( j \in \{ 1, \dots, s_i \} \) are the same. Then:
    \begin{equation*}
        2\pi \operatorname{i}\begin{bNiceMatrix}
			0 & \Cdots & 0 & \boldsymbol{v}_{i,1;0}^R & 0 &\Cdots & 0 & \boldsymbol{v}_{i,s_i;0}^R & 0 & \Cdots[shorten-end=8pt] 
		\end{bNiceMatrix} \boldsymbol{c} = 0. 
    \end{equation*}
    The nonzero entries correspond to positions \( \kappa_{i,1}, \dots, \kappa_{i,s_i} \), we obtain:
    \begin{equation*}
        \boldsymbol{v}_{i,1;0}^R c_{\kappa_{i,1}} + \boldsymbol{v}_{i,2;0}^R c_{\kappa_{i,2}} + \dots + \boldsymbol{v}_{i,s_i;0}^R c_{\kappa_{i,s_i}} = 0.
    \end{equation*}
    However, since the vectors \( \boldsymbol{v}_{i,j;0}^R \) are linearly independent, it follows that the only possible conclusion is \( c_{\kappa_{i,j}} = 0 \). We then multiply the preceding expression by \( (x-x_i)^{\kappa_{i,j}-2} \). The terms that exhibit a pole of multiplicity \( \geq \kappa_{i,j}-1 \) are precisely those for which we have already established that \( c_i = 0 \), along with the terms immediately preceding them. At this juncture, we could also consider the Jordan chains associated with a partial multiplicity equal to \( \kappa_{i,j}-1 \), and the deduction would remain valid. Furthermore, the poles of multiplicity \( \kappa_{i,j}-1 \) will similarly correspond to the associated eigenvectors \( \boldsymbol{v}_{i,j;0}^R \), and the same reasoning applies as previously discussed. 

    Consequently, we would systematically deduce that all entries of \( \boldsymbol{c} \) that are multiplied by the vector \( \mathbb{K}^{[n-1],(i)}(z) + \mathbb{P}^{(i)}(x) \) must be zero. Extending this conclusion for \( i \in\{1, \dots, M\} \), we ultimately arrive at the result \( \boldsymbol{c} = 0 \). Thus, we encounter a contradiction once again.

The perturbed matrix of measures is expressed in terms of the original measure and the matrix polynomial as
    \begin{equation*}
        \mathrm{d} \check{\mu}(x) = L^{-1}(x) \, \mathrm{d} \mu(x) + \sum_{i=1}^M \boldsymbol{v}_i^R \boldsymbol{\xi}_i(x) \delta(x - x_i),
    \end{equation*}
    where $\delta$ denotes Dirac’s delta distribution, $\boldsymbol{v}_i^R$ are the right eigenvectors of $L(x)$ associated with simple eigenvalues, and $\boldsymbol{\xi}_i(x)$ is an arbitrary row vector function of size $p$.

The connection matrix $\Omega$ can be expressed in two equivalent forms:
    \begin{equation*}
        \Omega = H^{-1} S L(\Lambda_{[q]}) \check{S}^{-1} \check{H} = \Bar{S}^{-\top} \check{\Bar{S}}^\top.
    \end{equation*}
    The connection matrix is upper unitriangular, with at most $M$ nonzero upper diagonals.

Based on Definitions \ref{D and W bb} and \ref{K bb}, we define:
    \begin{align*}
        \mathbb{C}_n^{(i)} &\coloneq \boldsymbol{v}_i^L C_n(x_i), \\
        \mathbb{W}_n^{(i)}&\coloneq \boldsymbol{v}_i^L L'(x_i) \boldsymbol{v}_i^R \boldsymbol{\xi}_i(x_i) A_n(x_i), \\
        \mathbb{K}^{[n],(i)}( y) &\coloneq \boldsymbol{v}_i^L K_C^{[n]}(x_i, y) - \boldsymbol{v}_i^L L'(x_i) \boldsymbol{v}_i^R \boldsymbol{\xi}_i(x_i) K^{[n]}(x_i, y).
    \end{align*}

The $\tau$-determinants are defined as follows:
    \begin{equation*}
        \tau_{n} \coloneq \begin{vNiceMatrix}
            \mathbb{C}_{n-M+1}^{(1)}- \mathbb{W}_{n-M+1}^{(1)}& \Cdots & \mathbb{C}_{n}^{(1)}- \mathbb{W}_{n}^{(1)}\\
            \Vdots & & \Vdots \\
            \mathbb{C}_{n-M+1}^{(M)}- \mathbb{W}_{n-M+1}^{(M)}& \Cdots & \mathbb{C}_{n}^{(M)}- \mathbb{W}_{n}^{(M)}
        \end{vNiceMatrix},
    \end{equation*}
    with $n \in \{ M-1, M, M-2, \dots \}$.

The Christoffel-type formulas for a left Geronimus perturbation are:
    \begin{align*}
        \check{B}_n^{(b)}(y) &= \frac{1}{\tau_n} \sum_{\tilde{b}=1}^q \begin{vNiceMatrix}
            \mathbb{C}_{n-M+1}^{(1)}- \mathbb{W}_{n-M+1}^{(1)}& \Cdots & \mathbb{C}_{n-1}^{(1)}- \mathbb{W}_{n-1}^{(1)}& \mathbb{K}_{\tilde{b}}^{[n-M],(1)}( y) + \frac{v_{1; \tilde{b}}^L}{y - x_1} \\
            \Vdots & & \Vdots & \Vdots \\
            \mathbb{C}_{n-M+1}^{(M)}- \mathbb{W}_{n-M+1}^{(M)}& \Cdots & \mathbb{C}_{n-1}^{(M)}- \mathbb{W}_{n-1}^{(M)}& \mathbb{K}_{\tilde{b}}^{[n-M],(M)}(y) + \frac{v_{M; \tilde{b}}^L}{y - x_M}
        \end{vNiceMatrix} L_{\tilde{b}, b}(x), \\
        \check{A}_n^{(a)}(x) &= \frac{1}{\tau_{n-1}} \begin{vNiceMatrix}
            \mathbb{C}_{n-M}^{(1)}- \mathbb{W}_{n-M}^{(1)}& \Cdots & \mathbb{C}_n^{(1)}- \mathbb{W}_n^{(1)}\\
            \Vdots & & \Vdots \\
            \mathbb{C}_{n-M}^{(M)}- \mathbb{W}_{n-M}^{(M)}& \Cdots & \mathbb{C}_n(x_M) - \mathbb{W}_n^{(M)}\\[2pt]
            A_{n-M}^{(a)}(x) & \Cdots & A_n^{(a)}(x)
        \end{vNiceMatrix}.
    \end{align*}

The Cauchy transform for the type II Jacobi--Piñeiro can be explicitly computed for $x=0$, in particular we have:
    \begin{align*}
        D_n^{(2)}(0;\alpha_1,\alpha_2,\alpha_3,\beta) & = - \Gamma(\beta+1) \sum_{l_1=0}^{n_1}\sum_{l_2=0}^{n_2}\sum_{l_3=0}^{n_3}
        \frac{C_{n}^{l_1,l_2,l_3}}{(\alpha_2+l_1+l_2+l_3)_{\beta+1}}, \\
        D_n^{(3)}(1;\alpha_1,\alpha_2,\alpha_3,\beta) & = \Gamma(\beta) \sum_{l_1=0}^{n_1}\sum_{l_2=0}^{n_2}\sum_{l_3=0}^{n_3}
        \frac{C_{n}^{l_1,l_2,l_3}}{(\alpha_3+l_1+l_2+l_3)_{\beta}}.
    \end{align*}

Let us study the following integral, 
    \begin{equation*}
        \int_0^1 x^{l_1+l_2+l_3+\alpha_2-1}(1-x)^\beta \operatorname{d} x = \dfrac{\Gamma(\beta+1)\Gamma(\alpha_2+l_1+l_2+l_3)}{\Gamma(\alpha_2+\beta+l_1+l_2+l_3+1)} = \dfrac{\Gamma(\beta+1)}{(\alpha_2+l_1+l_2+l_3)_{\beta+1}}, 
    \end{equation*}
    which is always valid, provided that $\alpha_2 > 0$. The Cauchy transform of the type II Jacobi--Piñeiro can be expressed as:
    \begin{align*}
        D_n^{(2)}(0;\alpha_1,\alpha_2,\alpha_3,\beta) & = - \int_0^1P_n(x;\alpha_1,\alpha_2,\alpha_3,\beta) \frac{\operatorname{d} \mu_2(x)}{x} = - \sum_{l_1=0}^{n_1}\sum_{l_2=0}^{n_2}\sum_{l_3=0}^{n_3}
        C_{n}^{l_1,l_2,l_3}\, \int_\Delta x^{l_1+l_2+l_3} \frac{\operatorname{d} \mu_2(x)}{x} \\
        & = - \sum_{l_1=0}^{n_1}\sum_{l_2=0}^{n_2}\sum_{l_3=0}^{n_3}
        C_{n}^{l_1,l_2,l_3}\, \int_\Delta x^{l_1+l_2+l_3+\alpha_2-1}(1-x)^\beta \operatorname{d} x.
    \end{align*}
    Substituting the first result in this equation yields the desired relation. To prove the second relation, one proceeds similarly for $D_n^{(3)}(1;\alpha_1,\alpha_2,\alpha_3,\beta)$.

For $n > 1$, the Christoffel type formula between the type I Jacobi--Piñeiro polynomials and the Geronimus  perturbed polynomials is:
    \begin{multline*}
        \begin{bNiceMatrix}
            \check{P}_{n}^{(1)}(x) \\
            \check{P}_{n}^{(2)}(x) \\
            \check{P}_{n}^{(3)}(x) 
        \end{bNiceMatrix} = \frac{-1}{\tau_n}\sum_{i=0}^{n-2} \begin{bNiceMatrix}
            x P_i^{(2)}(x) \\
            (1-x) P_i^{(3)}(x) \\
            P_i^{(1)}(x)
        \end{bNiceMatrix} \begin{vNiceMatrix}
            D_i^{(2)}(0)-P_i(0)\xi_0 & D_i^{(3)}(1)-P_i(1)\xi_1 \\[3pt]
            D_{n-1}^{(2)}(0)-P_{n-1}(0)\xi_0 & D_{n-1}^{(3)}(1)-P_{n-1}(1)\xi_1
        \end{vNiceMatrix} \\ + \frac{1}{\tau_n}\begin{bNiceMatrix}
            D_{n-1}^{(3)}(1)-P_{n-1}(1)\xi_1 \\
            -D_{n-1}^{(2)}(0)+P_{n-1}(0)\xi_0 \\
            0
        \end{bNiceMatrix}.
    \end{multline*}
        For $n > 1$,  the Christoffel type formula between the type II Jacobi--Piñeiro polynomials and the Geronimus  perturbed polynomials is:
    \begin{equation*}
        \check{P}_n(x) = \frac{1}{\tau_{n-1}}\begin{vNiceMatrix}
            D_{n-2}^{(2)}(0)-P_{n-2}(0)\xi_0 & D_{n-2}^{(3)}(1)-P_{n-2}(1)\xi_1 & P_{n-2}(x) \\[3pt]
            D_{n-1}^{(2)}(0)-P_{n-1}(0)\xi_0 & D_{n-1}^{(3)}(1)-P_{n-1}(1)\xi_1 & P_{n-1}(x) \\[3pt]
            D_{n}^{(2)}(0)-P_{n}(0)\xi_0 & D_{n}^{(3)}(1)-P_{n}(1)\xi_1 & P_{n}(x)
        \end{vNiceMatrix}.
    \end{equation*}

The following relations hold:
    \begin{align*}
        \mathbb{K}_a^{[n],(0)} &= \begin{multlined}[t][.8\textwidth]
        \frac{1}{x} \left[ \sum_{j=1}^{3}\sum_{l=1}^j T^{j}_{n+l}P^{(a)}_{n+l}(x)\left( D^{(2)}_{n-j}(0)-\xi_0P_{n-j}(0)-D_{n-j}^{(2)}(x)  \right) \right. \\ \left. - T^{0}_n P^{(a)}_n(x)\left( D^{(2)}_{n+1}(0)-\xi_0P_{n+1}(0)-D_{n+1}^{(2)}(x)  \right) \right], 
        \end{multlined}\\
         \mathbb{K}_a^{[n],(1)} &= \begin{multlined}[t][.8\textwidth] \frac{1}{(x-1)} \left[ \sum_{j=1}^{3}\sum_{l=1}^j T^{j}_{n+l}P^{(a)}_{n+l}(x)\left( D^{(3)}_{n-j}(1)-\xi_1P_{n-j}(1)-D_{n-j}^{(3)}(x)  \right) \right. \\ \left. - T^{0}_n P^{(a)}_n(x)\left( D^{(3)}_{n+1}(1)-\xi_1P_{n+1}(1)-D_{n+1}^{(3)}(x)  \right) \right].  \end{multlined}
    \end{align*}

For $n > 1$, the Christoffel type formula for $\check{P}^{(a)}_n(x)$ can be restated as: 
    \begin{multline*}
        \begin{bNiceMatrix}
            \check{P}_{n}^{(1)}(x) \\
            \check{P}_{n}^{(2)}(x) \\
            \check{P}_{n}^{(3)}(x) 
        \end{bNiceMatrix} = \frac{1}{\tau_n}\sum_{i=1}^{3} \sum_{j=1}^i T^j_{n+j} \begin{bNiceMatrix}
            x P_{n+j}^{(2)}(x) \\
            (1-x) P_{n+j}^{(3)}(x) \\
            P_{n+j}^{(1)}(x)
        \end{bNiceMatrix} \\ \times \begin{vNiceMatrix}
            D_{n-1}^{(2)}(0)-P_{n-1}(0)\xi_0 & D_{n-1}^{(3)}(1)-P_{n-1}(1)\xi_1 \\[3pt]
            \frac{1}{x}(D_{n-i}^{(2)}(0)-P_{n-i}(0)\xi_0 - D_{n-i}^{(2)}(x)) & \frac{1}{x-1}(D_{n-i}^{(3)}(1)-P_{n-i}(1)\xi_1 - D_{n-i}^{(3)}(x))
        \end{vNiceMatrix} \\[3pt] + \frac{1}{\tau_n} T^0_n \begin{bNiceMatrix}
            x P_{n+1}^{(2)}(x) \\
            (1-x) P_{n+1}^{(3)}(x) \\
            P_{n+1}^{(1)}(x)
        \end{bNiceMatrix}\begin{vNiceMatrix}
            D_{n-1}^{(2)}(0)-P_{n-1}(0)\xi_0 & D_{n-1}^{(3)}(1)-P_{n-1}(1)\xi_1 \\[3pt]
            D_{n+1}^{(2)}(0)-P_{n+1}(0)\xi_0 - D_{n+1}^{(2)}(x) & D_{n+1}^{(3)}(1)-P_{n+1}(1)\xi_1 - D_{n+1}^{(3)}(x)
        \end{vNiceMatrix} \\ + \frac{1}{\tau_n}\begin{bNiceMatrix}
            D_{n-1}^{(3)}(1)-P_{n-1}(1)\xi_1 \\
            -D_{n-1}^{(2)}(0)+P_{n-1}(0)\xi_0 \\
            0
        \end{bNiceMatrix}.
    \end{multline*}

\label{Non-cancellation}
	Perturbed orthogonality exists if the \(\tau\)-determinants are nonzero and there exist \(Np-r\) vector polynomials, \(\check{B}_n(x)\), satisfying: 
	\[
	\begin{aligned}
		\int_\Delta \sum_{b=1}^q \check{B}_n^{(b)}(x) \, \mathrm{d}\check{\mu}_{b,a}(x) \, x^l &= 0, & a &\in \{1,\dots,p\}, & l &\in \left\{0,\dots, \left\lceil\frac{n-a+2}{p}\right\rceil-1\right\},
	\end{aligned}
	\]
	for \(n \in \{0, \dots, Np-r-1\}\).

We introduce the following notation:
   \begin{equation}\label{eq:I}
   	\mathbb{I}_{i,l} \coloneq \int_\Delta B_i(x) \, \mathrm{d}\check{\mu}(x) \, \left( X_{[p]}^\top(x) \boldsymbol{e}_l \right).
   \end{equation}

We define new $\tilde{\tau}$-determinants as follows:
\[   \begin{aligned}
   	\tilde{\tau}_{n} &\coloneq 
   	\begin{vNiceMatrix}
   		\mathbb{I}_{0,0} & \Cdots & \mathbb{I}_{0,n} \\
   		\Vdots &        & \Vdots \\
   		\mathbb{I}_{n,0} & \Cdots & \mathbb{I}_{n,n}
   	\end{vNiceMatrix}, 
   & n &\in \{0, \dots, {Np-r}-1\}.
   \end{aligned}\]

Assume orthogonality exists despite $\tau_n = 0$ for some $n \in \{0, \dots, {Np-r}-2\}$. Since $\tau_n = \alpha_n \tau_{n-1}$ and $\tau_{n-1} \neq 0$, the only possibility is $\alpha_n = 0$. However,
	\begin{equation*}
		\int_\Delta \check{B}_n(x) \, \mathrm{d}\check{\mu}(x) \, \left( X_{[p]}^\top(x) \boldsymbol{e}_n \right) = \alpha_n,
	\end{equation*}
	and orthogonality would not be satisfied.
